from __future__ import annotations

PAGE = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Threatline</title><style>
:root{font-family:Inter,ui-sans-serif,system-ui,sans-serif;color:#e7e9ee;background:#0d0f13}*{box-sizing:border-box}body{margin:0}.shell{max-width:1180px;margin:auto;padding:28px}.top{display:flex;align-items:center;justify-content:space-between;gap:20px}.brand{font-size:25px;font-weight:760;letter-spacing:-.03em}.eyebrow{color:#8490a4;font-size:12px;text-transform:uppercase;letter-spacing:.12em}.status{font-size:12px;border:1px solid #2c5d42;color:#9be7b2;border-radius:999px;padding:7px 11px}.hero{padding:42px 0 24px;border-bottom:1px solid #242a34}.hero h1{font-size:38px;margin:5px 0 8px;letter-spacing:-.04em}.hero p{color:#9fa9ba;margin:0;max-width:760px}.nav{display:flex;gap:8px;margin:22px 0;flex-wrap:wrap}.nav button,.filters button,.action{background:#171b22;color:#b8c0ce;border:1px solid #2b313c;border-radius:9px;padding:9px 13px;cursor:pointer}.nav button.active,.action.primary{background:#e9edf5;color:#11151b;border-color:#e9edf5}.filters{display:flex;gap:8px;flex-wrap:wrap;margin:0 0 16px}.filters input,.filters select,.field,textarea{background:#141820;color:#dfe4ec;border:1px solid #2b313c;border-radius:9px;padding:9px 11px}.summary{display:flex;justify-content:space-between;align-items:end;margin:20px 0 8px}.summary h2,.panel h2{margin:0;font-size:18px}.muted{color:#8d98aa;font-size:13px}.list{border:1px solid #272d37;border-radius:14px;background:#13171d;overflow:hidden}.row{display:grid;grid-template-columns:82px 1fr 155px 120px;gap:14px;padding:15px 17px;border-top:1px solid #242a33;align-items:center}.row:first-child{border-top:0}.row-main{background:none;border:0;color:inherit;text-align:left;padding:0;cursor:pointer;font:inherit}.score{font-size:12px;color:#aab4c4}.score strong{display:block;font-size:20px;color:#f0f3f7}.title{font-weight:660}.key{color:#8ca8ff;font-size:12px;margin-bottom:3px}.reason{color:#929daf;font-size:12px;margin-top:5px}.owner,.priority{color:#b5becc;font-size:13px}.priority.high,.priority.critical,.priority.highest{color:#ff9e91}.empty,.error{padding:28px;color:#949faf}.panel{border:1px solid #272d37;border-radius:14px;background:#13171d;padding:20px}.panel-head{display:flex;justify-content:space-between;gap:16px;align-items:end;margin-bottom:18px}.form-row{display:grid;grid-template-columns:170px 1fr;gap:10px;margin-bottom:10px}.form-row .field{width:100%}.note-compose textarea{width:100%;min-height:110px;resize:vertical;margin:0 0 10px}.note-item{border-top:1px solid #242a33;padding:13px 0}.note-item:first-child{border-top:0}.note-text{white-space:pre-wrap}.handoff-editor{width:100%;min-height:460px;resize:vertical;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;line-height:1.5}.toolbar{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}.flash{font-size:12px;color:#9be7b2;min-height:18px;margin-top:7px}.drawer-backdrop{position:fixed;inset:0;background:#05070a99;z-index:10}.drawer{position:fixed;top:0;right:0;width:min(720px,94vw);height:100vh;background:#10141a;border-left:1px solid #303743;z-index:11;overflow:auto;box-shadow:-20px 0 60px #0008}.drawer-head{position:sticky;top:0;background:#10141af5;backdrop-filter:blur(12px);padding:24px 26px;border-bottom:1px solid #29303a;display:flex;justify-content:space-between;gap:20px;z-index:2}.drawer-head h2{margin:4px 0 7px;font-size:24px}.close{background:#1b2028;border:1px solid #323a46;color:#d7dde7;border-radius:8px;width:36px;height:36px;font-size:19px;cursor:pointer}.drawer-body{padding:22px 26px 42px}.meta{display:flex;gap:8px;flex-wrap:wrap;margin:8px 0 22px}.chip{border:1px solid #303844;border-radius:999px;padding:6px 9px;color:#aeb8c7;font-size:12px}.section{margin:28px 0}.section h3{font-size:13px;text-transform:uppercase;letter-spacing:.09em;color:#8d99aa;margin:0 0 10px}.context-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.context-card{border:1px solid #29313c;background:#151a21;border-radius:11px;padding:12px}.context-card a{color:#d9e1ee;text-decoration:none}.context-card a:hover{text-decoration:underline}.context-title{font-weight:650;font-size:14px}.context-sub{color:#8e99aa;font-size:12px;margin-top:5px}.timeline{border-left:1px solid #303846;margin-left:7px}.event{position:relative;padding:0 0 18px 22px}.event:before{content:'';position:absolute;width:9px;height:9px;border-radius:50%;background:#7c96ff;left:-5px;top:5px}.event-kind{color:#8492a6;font-size:11px;text-transform:uppercase;letter-spacing:.08em}.event-title{font-weight:650;margin-top:2px}.event-detail{color:#949faf;font-size:12px;margin-top:3px}.event-time{color:#697487;font-size:11px;margin-top:4px}.source-link{display:inline-block;color:#9fb3ff;text-decoration:none;font-size:12px;margin-top:5px}.source-link:hover{text-decoration:underline}[hidden]{display:none!important}@media(max-width:760px){.row{grid-template-columns:65px 1fr}.owner,.priority{display:none}.hero h1{font-size:31px}.shell{padding:20px}.context-grid,.form-row{grid-template-columns:1fr}.drawer-body,.drawer-head{padding-left:18px;padding-right:18px}}
</style></head><body><main class="shell"><header class="top"><div><div class="eyebrow">Engineering operations</div><div class="brand">Threatline</div></div><div class="status">Local workspace</div></header><section class="hero"><div class="eyebrow">Operational context, not another vendor tab</div><h1>Know what needs attention.</h1><p>Threatline connects active work to alerts, source changes, runbooks, meetings and decisions—and keeps the operator's notes and handoff local.</p></section><nav class="nav"><button data-mode="today" class="active">Today</button><button data-mode="queue">Queue</button><button data-mode="notes">Daily Notes</button><button data-mode="handoff">Handoff</button></nav><section id="workView"><section id="filters" class="filters" hidden><input id="q" placeholder="Search key, title, tag"><select id="priority"><option value="">Any priority</option><option>critical</option><option>highest</option><option>high</option><option>medium</option><option>normal</option><option>low</option></select><select id="ownership"><option value="any">Any owner</option><option value="unassigned">Unassigned</option><option value="assigned">Assigned</option></select><select id="sort"><option value="attention">Attention</option><option value="updated">Recently updated</option><option value="oldest">Oldest</option><option value="priority">Priority</option></select><button id="apply">Apply</button></section><section class="summary"><div><h2 id="heading">Needs attention</h2><div id="subheading" class="muted">Deterministic ranking; every score has a reason.</div></div><div id="count" class="muted"></div></section><section id="list" class="list"><div class="empty">Loading…</div></section></section><section id="notesView" class="panel" hidden><div class="panel-head"><div><h2>Daily Notes</h2><div class="muted">Stored locally. Attach a note to a work item when it belongs in that item's handoff.</div></div><input id="notesDate" class="field" type="date"></div><div class="note-compose"><div class="form-row"><input id="noteWorkItem" class="field" placeholder="Work item (optional, e.g. OPS-142)"><div></div></div><textarea id="noteText" placeholder="What should you remember or hand off?"></textarea><button id="saveNote" class="action primary">Save note</button><div id="noteFlash" class="flash"></div></div><section class="section"><h3>Saved notes</h3><div id="notesList" class="muted">No notes yet.</div></section></section><section id="handoffView" class="panel" hidden><div class="panel-head"><div><h2>Shift Handoff</h2><div class="muted">Generated only from locally recorded activity, notes, and current connected work state. Edit before sharing.</div></div><input id="handoffDate" class="field" type="date"></div><textarea id="handoffText" class="handoff-editor" spellcheck="true"></textarea><div class="toolbar"><button id="generateHandoff" class="action primary">Regenerate</button><button id="copyHandoff" class="action">Copy Markdown</button></div><div id="handoffFlash" class="flash"></div></section></main><div id="backdrop" class="drawer-backdrop" hidden></div><aside id="drawer" class="drawer" hidden aria-label="Investigation"><div class="drawer-head"><div><div id="investigationKey" class="key"></div><h2 id="investigationTitle">Investigation</h2><div id="investigationState" class="muted"></div></div><button id="closeDrawer" class="close" aria-label="Close investigation">×</button></div><div id="drawerBody" class="drawer-body"><div class="empty">Loading…</div></div></aside><script>
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl=s=>{try{const u=new URL(String(s||''),location.origin);return ['http:','https:'].includes(u.protocol)?u.href:''}catch{return ''}};
const localDay=()=>{const d=new Date(),off=d.getTimezoneOffset();return new Date(d.getTime()-off*60000).toISOString().slice(0,10)};
const list=document.getElementById('list'),count=document.getElementById('count'),filters=document.getElementById('filters');let mode='today';
document.getElementById('notesDate').value=localDay();document.getElementById('handoffDate').value=localDay();
function row(v){const i=v.work_item||{};const reasons=(v.reasons||[]).join(' · ');return `<div class="row"><div class="score"><strong>${esc(v.score)}</strong>attention</div><button class="row-main" data-investigate="${esc(i.id)}"><div class="key">${esc(i.id)}</div><div class="title">${esc(i.title)}</div><div class="reason">${esc(reasons)}</div></button><div class="owner">${esc(i.assignee||'Unassigned')}</div><div class="priority ${esc((i.priority||'').toLowerCase())}">${esc(i.priority||'normal')}<div class="muted">${esc(i.status||'')}</div></div></div>`}
async function loadWork(){list.innerHTML='<div class="empty">Loading…</div>';try{let url='/api/today';if(mode==='queue'){const p=new URLSearchParams();for(const id of ['q','priority','ownership','sort']){const v=document.getElementById(id).value;if(v)p.set(id,v)}url='/api/queue?'+p.toString()}const r=await fetch(url);if(!r.ok)throw new Error('request failed');const d=await r.json();const items=d.items||[];list.innerHTML=items.length?items.map(row).join(''):'<div class="empty">Nothing matches this view.</div>';count.textContent=`${items.length} item${items.length===1?'':'s'}`}catch(e){list.innerHTML='<div class="error">Unable to load work. Check provider diagnostics.</div>';count.textContent=''}}
function setMode(next){mode=next;document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===next));document.getElementById('workView').hidden=!['today','queue'].includes(next);document.getElementById('notesView').hidden=next!=='notes';document.getElementById('handoffView').hidden=next!=='handoff';filters.hidden=next!=='queue';if(next==='today'||next==='queue'){document.getElementById('heading').textContent=next==='today'?'Needs attention':'Operational queue';document.getElementById('subheading').textContent=next==='today'?'Deterministic ranking; every score has a reason.':'Filter and sort normalized work across connected providers.';loadWork()}else if(next==='notes'){loadNotes()}else if(next==='handoff'){loadHandoff()}}
function sourceLink(obj,label='Open source'){const url=safeUrl(obj&&obj.source_ref&&obj.source_ref.url);return url?`<a class="source-link" href="${esc(url)}" target="_blank" rel="noreferrer">${esc(label)} ↗</a>`:''}
function collection(title,items,kind){if(!items||!items.length)return `<section class="section"><h3>${esc(title)}</h3><div class="muted">No ${esc(title.toLowerCase())} linked yet.</div></section>`;return `<section class="section"><h3>${esc(title)}</h3><div class="context-grid">${items.map(i=>{const label=i.title||i.summary||i.id;const sub=i.author||i.severity||i.location||i.source||kind||'';const direct=safeUrl(i.location);const link=direct?`<a class="source-link" href="${esc(direct)}" target="_blank" rel="noreferrer">Open ↗</a>`:sourceLink(i);return `<div class="context-card"><div class="context-title">${esc(label)}</div><div class="context-sub">${esc(sub)}</div>${link}</div>`}).join('')}</div></section>`}
function timeline(events){if(!events||!events.length)return '<div class="muted">No dated activity available.</div>';return `<div class="timeline">${events.map(e=>{const url=safeUrl(e.url);return `<div class="event"><div class="event-kind">${esc(e.kind)} · ${esc(e.source)}</div><div class="event-title">${esc(e.title)}</div>${e.detail?`<div class="event-detail">${esc(e.detail)}</div>`:''}<div class="event-time">${esc(new Date(e.timestamp).toLocaleString())}</div>${url?`<a class="source-link" href="${esc(url)}" target="_blank" rel="noreferrer">Open source ↗</a>`:''}</div>`}).join('')}</div>`}
async function postJSON(url,payload){const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok){let message='Request failed';try{const d=await r.json();message=d.error||message}catch{}throw new Error(message)}return r.json()}
async function openInvestigation(id){document.getElementById('backdrop').hidden=false;document.getElementById('drawer').hidden=false;document.getElementById('drawerBody').innerHTML='<div class="empty">Loading investigation…</div>';try{const r=await fetch('/api/investigations/'+encodeURIComponent(id));if(!r.ok)throw new Error('not found');const d=await r.json(),w=d.work_item||{};postJSON('/api/activity',{kind:'investigation_opened',work_item_id:id,summary:'Opened investigation'}).catch(()=>{});document.getElementById('investigationKey').textContent=w.id||id;document.getElementById('investigationTitle').textContent=w.title||'Investigation';document.getElementById('investigationState').textContent=`${w.status||''} · ${w.priority||'normal'} priority`;const owner=d.ownership||{};const source=sourceLink(w,'Open work item');document.getElementById('drawerBody').innerHTML=`<div class="meta"><span class="chip">${esc(owner.assignee||'Unassigned')}</span>${owner.service_owner?`<span class="chip">Service: ${esc(owner.service_owner)}</span>`:''}${w.source?`<span class="chip">${esc(w.source)}</span>`:''}</div>${source}<section class="section"><h3>Operational timeline</h3>${timeline(d.timeline)}</section>${collection('Alerts',d.alerts,'alert')}${collection('Related changes',d.changes,'change')}${collection('Runbooks',d.runbooks,'runbook')}${collection('Meetings',d.meetings,'meeting')}${collection('Decisions',d.decisions,'decision')}`;}catch(e){document.getElementById('drawerBody').innerHTML='<div class="error">Unable to build this investigation. Check connected providers.</div>'}}
function closeInvestigation(){document.getElementById('backdrop').hidden=true;document.getElementById('drawer').hidden=true}
async function loadNotes(){const day=document.getElementById('notesDate').value||localDay();const r=await fetch('/api/notes?date='+encodeURIComponent(day));const d=await r.json();const notes=d.notes||[];document.getElementById('notesList').innerHTML=notes.length?notes.map(n=>`<div class="note-item"><div class="note-text">${esc(n.text)}</div><div class="muted">${n.work_item_id?esc(n.work_item_id)+' · ':''}${esc(new Date(n.created_at).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}))}</div></div>`).join(''):'<div class="muted">No notes recorded for this date.</div>'}
async function saveNote(){const text=document.getElementById('noteText').value,work=document.getElementById('noteWorkItem').value;const flash=document.getElementById('noteFlash');flash.textContent='';try{await postJSON('/api/notes',{text,work_item_id:work||null});document.getElementById('noteText').value='';flash.textContent='Saved locally.';await loadNotes()}catch(e){flash.textContent=e.message}}
async function loadHandoff(){const day=document.getElementById('handoffDate').value||localDay(),flash=document.getElementById('handoffFlash');flash.textContent='';try{const r=await fetch('/api/handoff?date='+encodeURIComponent(day));if(!r.ok)throw new Error('Unable to generate handoff');const d=await r.json();document.getElementById('handoffText').value=d.markdown||''}catch(e){flash.textContent=e.message}}
async function copyHandoff(){const text=document.getElementById('handoffText').value,flash=document.getElementById('handoffFlash');try{await navigator.clipboard.writeText(text);flash.textContent='Copied Markdown.'}catch{flash.textContent='Clipboard access was not available.'}}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));document.getElementById('apply').onclick=loadWork;document.getElementById('q').addEventListener('keydown',e=>{if(e.key==='Enter')loadWork()});list.addEventListener('click',e=>{const b=e.target.closest('[data-investigate]');if(b)openInvestigation(b.dataset.investigate)});document.getElementById('closeDrawer').onclick=closeInvestigation;document.getElementById('backdrop').onclick=closeInvestigation;document.addEventListener('keydown',e=>{if(e.key==='Escape')closeInvestigation()});document.getElementById('notesDate').onchange=loadNotes;document.getElementById('saveNote').onclick=saveNote;document.getElementById('handoffDate').onchange=loadHandoff;document.getElementById('generateHandoff').onclick=loadHandoff;document.getElementById('copyHandoff').onclick=copyHandoff;loadWork();
</script></body></html>'''
